'use strict';
// Remaining page designs, sharing the same fixture records as the first batch.
function initialTasks(){return [
 {id:'java',title:'Java实验报告',category:'study',tags:['report'],due:'2026-09-25',clock:'18:00',remaining:60,status:'active',records:[],version:1},
 {id:'materials',title:'奖学金申请材料',category:'affairs',tags:['material'],due:'2026-09-25',clock:'12:00',remaining:30,status:'active',records:[],version:1},
 {id:'prob-review',title:'概率论复习',category:'study',tags:['review'],due:null,clock:null,remaining:120,status:'active',records:[],version:1}
];}
function weekStart(week){return dateAdd('2026-08-31',(week-1)*7);}
function inWeek(r,week){return r.date>=weekStart(week)&&r.date<=dateAdd(weekStart(week),6);}
function shortTitle(r){return ({'计算机图形学':'图形学','Python程序设计':'Python','Java实验报告':'Java报告','课题组组会':'组会','数据库原理':'数据库','材料办理':'材料'})[r.title]||r.title;}
function calendarRows(){return rows.filter(r=>inWeek(r,state.calendarWeek)&&r.kind!=='progress'&&(state.scheduleFilter==='all'||r.kind===state.scheduleFilter));}
function weekControls(){return `<div class="week-toolbar"><button class="icon-button" data-action="week-prev" aria-label="上一周" ${state.calendarWeek===1?'disabled':''}>${icon('left')}</button><button class="week-picker" data-action="week-picker">第${state.calendarWeek}周 ${icon('down')}<small>${shortDate(weekStart(state.calendarWeek))}—${shortDate(dateAdd(weekStart(state.calendarWeek),6))}</small></button><button class="icon-button" data-action="week-next" aria-label="下一周" ${state.calendarWeek===20?'disabled':''}>${icon('right')}</button><button class="text-button" data-action="week-current">回本周</button></div>`;}
function calendarDayStrip(){return `<div class="week-strip calendar-days">${Array.from({length:7},(_,i)=>{const d=dateAdd(weekStart(state.calendarWeek),i);return `<button data-action="calendar-day" data-day="${d}" class="${state.day===d?'selected':''}" aria-label="查看${dateLabel(d)}">${weekday(d)}<b>${Number(d.slice(8))}</b></button>`;}).join('')}</div>`;}
function partitionEvents(events){
 const sorted=[...events].sort((a,b)=>timeNumber(a.start)-timeNumber(b.start)||timeNumber(a.end)-timeNumber(b.end));
 const groups=[];let group=[],until=-1;
 for(const e of sorted){if(timeNumber(e.start)>=until&&group.length){groups.push(group);group=[];until=-1;}group.push(e);until=Math.max(until,timeNumber(e.end));}if(group.length)groups.push(group);
 return groups.flatMap(g=>{const ends=[];const allocated=g.map(e=>{let lane=ends.findIndex(end=>end<=timeNumber(e.start));if(lane<0)lane=ends.length;ends[lane]=timeNumber(e.end);return {event:e,lane};});return allocated.map(a=>({...a,lanes:ends.length}));});
}
function calendarGrid(list){const start=weekStart(state.calendarWeek);return `<div class="calendar-scroll" aria-label="周课表，可滚动查看时段"><div class="calendar-canvas"><div class="grid-week-head"><span class="time-heading">时间</span>${Array.from({length:7},(_,i)=>{const d=dateAdd(start,i);return `<button data-action="calendar-day" data-day="${d}" class="${d===state.day?'selected':''}">周${weekday(d)}<b>${Number(d.slice(8))}</b></button>`;}).join('')}</div><div class="time-grid">${Array.from({length:14},(_,i)=>`<span class="grid-hour" style="top:${i*49}px">${8+i}:00</span><i class="hour-rule" style="top:${i*49}px"></i>`).join('')}${Array.from({length:7},(_,i)=>{const d=dateAdd(start,i);return `<div class="grid-day" style="left:calc(32px + (100% - 32px)*${i}/7);width:calc((100% - 32px)/7)">${partitionEvents(list.filter(r=>r.date===d&&r.start&&r.end)).map(({event:r,lane,lanes})=>`<button class="calendar-event ${r.kind==='plan'?'personal':''} ${lanes>1?'overlap':''}" data-action="detail" data-id="${r.id}" aria-label="${r.title} ${dateLabel(d)} ${r.start}至${r.end}${lanes>1?' 与其他安排重叠':''}" style="${categoryStyle(r.category)};top:${(timeNumber(r.start)-480)/60*49}px;height:${duration(r)/60*49-3}px;left:calc(${lane/lanes*100}% + 2px);width:calc(${100/lanes}% - 4px)"><b>${shortTitle(r)}</b><small>${r.start}</small>${lanes>1?'<i class="overlap-dot"></i>':''}</button>`).join('')}</div>`;}).join('')}${state.calendarWeek===4?'<div class="now-line" style="top:179.7px"><span>11:40</span></div>':''}</div></div></div>`;}
function schedulePage(){const list=calendarRows();const dayRows=list.filter(r=>r.date===state.day).sort((a,b)=>(a.start||a.due||'').localeCompare(b.start||b.due||''));return `${weekControls()}${state.loadFailure?`<div class="retry-banner">更新失败，正在显示已有记录<button data-action="retry-calendar">重试</button></div>`:''}<div class="calendar-view-row"><div class="range-selector"><button data-action="calendar-mode" data-mode="week" class="${state.calendarMode==='week'?'selected':''}">周课表</button><button data-action="calendar-mode" data-mode="day" class="${state.calendarMode==='day'?'selected':''}">按天查看</button></div><button class="text-button" data-action="schools">导入课表</button></div><div class="type-filters" aria-label="日程类型">${[['all','全部'],['course','课程'],['activity','活动'],['plan','个人计划'],['deadline','截止']].map(([id,n])=>`<button data-action="schedule-filter" data-filter="${id}" class="${state.scheduleFilter===id?'selected':''}">${n}</button>`).join('')}</div>${state.calendarMode==='week'?calendarGrid(list):calendarDayStrip()}${section(`${dateLabel(state.day)} 周${weekday(state.day)}`)}<div class="list-card">${dayRows.map(rowButton).join('')||'<div class="empty-state">'+icon('calendar')+'<h3>当天暂无这类安排</h3><p>可以切换日期或日程类型。</p></div>'}</div><div class="grid-legend"><span><i></i>固定安排</span><span><i class="personal"></i>个人计划</span><span><i class="overlap"></i>时间重叠</span></div>`;}
function taskPlan(t){return t.id==='java'?rows.find(r=>r.id==='java'):null;}
function taskCard(t){const p=taskPlan(t);return `<article class="task-tile" style="${categoryStyle(t.category)}"><div class="task-title-row"><button class="task-name" data-action="task-detail" data-task="${t.id}"><span class="task-symbol">${icon(CATEGORY[t.category].icon)}</span><span>${t.title}</span></button><button class="task-complete ${t.status==='completed'?'checked':''}" data-action="progress" data-task="${t.id}" aria-label="${t.status==='completed'?'查看':'记录'}${t.title}进度">${icon(t.status==='completed'?'check':'plan')}</button></div><div class="task-labels"><span class="tag" style="color:var(--category-color);background:var(--category-pale)">${CATEGORY[t.category].name}</span>${t.tags.map(tag=>`<span class="tag label">${TAG_NAMES[tag]}</span>`).join('')}</div><div class="task-metrics"><span>${t.status==='completed'?'已完成':t.due?`${shortDate(t.due)} ${t.clock}截止`:'截止日期未定'}</span><b>${t.status==='completed'?t.records.some(r=>r.minutes!=null)?'已记录'+t.records.reduce((a,r)=>a+(r.minutes||0),0)+'分钟':'未记录实际时长':'剩余'+t.remaining+'分钟'}</b></div>${p?`<button class="planned-slot" data-action="detail" data-id="${p.id}">${icon('clock')}<span>周${weekday(p.date)} ${p.start}—${p.end}</span>${conflict()?'<b>冲突</b>':icon('right')}</button>`:t.status==='active'?`<button class="text-button" data-action="task-plan" data-task="${t.id}">安排时间 →</button>`:''}${t.id==='java'&&state.undoAvailable&&t.status==='active'?'<button class="text-button" data-action="undo">撤销本次调整</button>':''}</article>`;}
function plansPage(){const tasks=state.tasks.filter(t=>state.planFilter==='completed'?t.status==='completed':t.status==='active');return `<div class="plan-overview"><div><strong>${state.tasks.filter(t=>t.status==='active').length}</strong><span>待完成</span></div><div><strong>${state.tasks.filter(t=>t.status==='completed').length}</strong><span>已完成</span></div><button data-action="availability">${icon('settings')}可学习时间</button></div><div class="plan-tabs"><button data-action="plan-filter" data-filter="active" class="${state.planFilter==='active'?'selected':''}">待完成</button><button data-action="plan-filter" data-filter="completed" class="${state.planFilter==='completed'?'selected':''}">已完成</button></div>${conflict()?'<button class="conflict-note" data-action="replan" style="width:100%;text-align:left">'+icon('info')+'组会与报告计划在周三17:00重叠</button>':''}<div class="tasks-list">${tasks.map(taskCard).join('')||`<div class="empty-state">${icon('check')}<h3>${state.planFilter==='completed'?'暂无完成记录':'当前没有待完成任务'}</h3></div>`}</div>${state.planFilter==='active'?'<button class="primary" data-action="assistant" style="margin-top:8px">'+icon('spark')+' 用一句话安排任务</button>':''}<button class="quiet-link" data-action="progress-history">进度记录${icon('right')}</button>`;}
function semesterNodes(){const w=state.semesterWeek;const nodes=rows.filter(r=>inWeek(r,w)&&['deadline','activity'].includes(r.kind)).map(r=>({...r,sort:r.date,caption:dateLabel(r.date)+' · '+(r.start||r.due)+(r.kind==='deadline'?'截止':'')}));if(w===14)nodes.push({id:'exam-prob',title:'概率论考试',category:'study',kind:'exam',sort:'2026-11-30',caption:'暂定第14周 · 日期待确认'});return nodes.filter(r=>state.semesterFilter==='all'||r.kind===state.semesterFilter).sort((a,b)=>a.sort.localeCompare(b.sort));}
function semesterPage(){const w=state.semesterWeek,list=semesterNodes();const courseCount=rows.filter(r=>inWeek(r,w)&&r.kind==='course').length;return `<div class="semester-summary"><div><div class="summary-label">2026—2027 第一学期</div><h2>第4周<small> / 共20周</small></h2><p>8月31日开学</p></div><button class="semester-chart-button" data-action="analytics">${icon('chart')}<span>统计分析</span></button></div><div class="semester-week-map" aria-label="学期周次">${Array.from({length:20},(_,i)=>{const x=i+1;const count=rows.filter(r=>inWeek(r,x)&&['deadline','activity'].includes(r.kind)).length+(x===14?1:0);return `<button data-action="semester-week" data-week="${x}" class="${w===x?'selected':''} ${x<4?'past':''}" aria-label="第${x}周${count?'，有'+count+'项事项':''}"><b>${x}</b><span>${x===4?'本周':count?'·'.repeat(Math.min(count,3)):' '}</span></button>`;}).join('')}</div><div class="semester-period"><strong>第${w}周</strong><span>${shortDate(weekStart(w))}—${shortDate(dateAdd(weekStart(w),6))}</span>${w!==4?'<button data-action="semester-current">回本周</button>':''}</div><div class="type-filters">${[['all','全部'],['exam','考试'],['deadline','截止'],['activity','活动']].map(([v,n])=>`<button data-action="semester-filter" data-filter="${v}" class="${state.semesterFilter===v?'selected':''}">${n}</button>`).join('')}</div><div class="semester-timeline">${list.map(r=>`<button class="timeline-node" style="${categoryStyle(r.category)}" data-action="${r.kind==='exam'?'exam-detail':'detail'}" data-id="${r.id}"><span class="node-dot"></span><small>${r.caption}</small><b>${r.title}</b><span>${r.place||'考试时间尚未确定'}</span></button>`).join('')||'<div class="empty-state"><h3>这一周暂无这类事项</h3><p>可以切换周次或类型。</p></div>'}</div><div class="semester-bottom"><span>第${w}周已记录${courseCount}次课程</span><button data-action="semester-calendar">查看日程 →</button></div>${section('学期管理')}<button class="quiet-link" data-action="courses">${icon('book')}课程列表${icon('right')}</button><button class="quiet-link" data-action="exam-detail">${icon('calendar')}考试与复习${icon('right')}</button><button class="quiet-link" data-action="schools">${icon('folder')}导入课表${icon('right')}</button>`;}
function secondBatchView(){return state.view==='schedule'?schedulePage():state.view==='plans'?plansPage():semesterPage();}
function progressRecords(){return state.tasks.flatMap(t=>t.records.map(r=>({...r,title:t.title,task:t.id}))).reverse();}
function secondBatchSheet(){
 const t=state.tasks.find(t=>t.id===state.selectedTask);
 switch(state.modal){
 case 'week-picker':sheet('选择周次',`<p class="plain-copy">当前为第4周，学期共20周。</p><div class="week-overview">${Array.from({length:20},(_,i)=>`<button data-action="week-select" data-week="${i+1}" class="${state.calendarWeek===i+1?'selected':''}">${i+1}周</button>`).join('')}</div>`);return true;
 case 'task-detail':sheet('任务详情',`<div class="result-card"><div class="result-kicker">${CATEGORY[t.category].name}</div><h3>${t.title}</h3><div class="result-line">${icon('calendar')}<span>${t.due?dateLabel(t.due)+' '+t.clock+'截止':'截止日期未确定'}</span></div><div class="result-line">${icon('clock')}<span>${t.status==='completed'?'已完成':'剩余工作量 '+t.remaining+'分钟'}</span></div><div class="tag-editor">${t.tags.map(tag=>`<span class="tag label">${TAG_NAMES[tag]}</span>`).join('')}</div></div><button class="primary" data-action="progress" data-task="${t.id}">${t.status==='completed'?'查看完成记录':'记录进度'}</button>`);return true;
 case 'progress':if(t.status==='completed'){sheet('完成记录',`<div class="success-note">${icon('check')}${t.title}已完成</div><p class="plain-copy">${t.records.at(-1).minutes==null?'未填写实际投入时长。':'本次记录'+t.records.at(-1).minutes+'分钟。'}${t.id==='java'?'剩余的报告学习时段已取消。':''}</p><button class="secondary" data-action="undo-progress" data-task="${t.id}">撤销这条完成记录</button>`);}else sheet('记录进度',`<h3 style="font-size:18px;margin-bottom:14px">${t.title}</h3><label class="field">本次实际投入（分钟，可不填）<input id="spent-minutes" type="number" min="1" max="1440" placeholder="例如：30"></label><label class="completion-choice"><input id="task-done" type="checkbox">这个任务已经完成</label><p class="notice-text">只记录投入时长，不会自动减少剩余工作量。</p><p id="progress-error" class="form-error" role="alert"></p><button class="primary" data-action="save-progress" data-task="${t.id}">保存进度</button>`);return true;
 case 'progress-history':sheet('进度记录',`${progressRecords().map(r=>`<div class="history-row"><b>${r.title}</b><span>${r.completed?'已完成':'记录投入'} · ${r.minutes==null?'未填写时长':r.minutes+'分钟'}</span><small>9月23日</small></div>`).join('')||'<div class="empty-state"><h3>暂无进度记录</h3></div>'}`);return true;
 case 'availability':sheet('可学习时间',`<div class="result-card"><div class="result-line"><span>周三</span><b>17:00—18:00</b></div><div class="result-line"><span>周四</span><b>16:00—17:00</b></div></div><p class="plain-copy">这是本例排程使用的时间范围。AI不会把其他无课时间自动当作可学习时间。</p><button class="primary" data-action="assistant">向AI说明时间偏好</button>`);return true;
 case 'task-plan':sheet('安排任务',`<h3>${t.title}</h3><p class="plain-copy">${t.id==='java'?'已有学习时段，可通过组会示例查看调整过程。':'这一任务没有预置排程结果。正式Agent会查询可学习时间后生成方案。'}</p><button class="primary" data-action="assistant">打开AI助手</button>`);return true;
 case 'task-already-done':sheet('任务已完成','<p class="plain-copy">Java实验报告已完成，不需要再调整它的学习时间。已记录的组会继续保留。</p><button class="primary" data-action="plans">查看任务</button>');return true;
 case 'exam-detail':sheet('概率论考试','<div class="result-card"><div class="result-kicker">学业 · 考试</div><h3>暂定第14周</h3><p class="plain-copy">具体日期和考试时长尚未公布。</p></div><button class="primary" data-action="exam-review">查看复习任务</button>');return true;
 case 'courses':{const unique=[...new Map(rows.filter(r=>r.kind==='course').map(r=>[r.title,r])).values()];sheet('课程列表',unique.map(r=>`<button class="quiet-link" data-action="detail" data-id="${r.id}">${r.title}${icon('right')}</button>`).join(''));return true;}
 case 'schools':sheet('选择学校','<input class="school-search" id="school-query" aria-label="搜索学校" placeholder="搜索学校"><div id="school-result">'+schoolChoice()+'</div><p class="notice-text">目前仅适配河南工业大学。</p>');return true;
 case 'school-login':sheet('河南工业大学','<div class="result-card"><div class="result-kicker">学校教务系统</div><h3 style="font-size:17px">jwglxt.haut.edu.cn</h3><p class="plain-copy">正式App会打开学校原站。此原型不连接教务，也不收集密码。</p></div><button class="primary" data-action="import-preview">查看示例导入预览</button>');return true;
 case 'import-preview':sheet('导入预览','<div class="success-note">示例课表 · 7门课程</div><p class="plain-copy">当前示例已有这些课程。相同课表重复导入不会新增重复课次。</p><button class="primary" data-action="confirm-import">确认示例导入</button>');return true;
 case 'import-result':sheet('导入结果','<div class="receipt-title"><div class="check-circle">'+icon('check')+'</div><h3>课表已核对</h3><p>7门课程相同，没有重复添加。</p></div><button class="primary" data-action="schedule">查看课表</button>');return true;
 default:return false;
 }
}
function schoolChoice(){return `<button class="school-choice" data-action="school-login"><span class="task-symbol">${icon('book')}</span><span><b>河南工业大学</b><small>可导入 · 正方教务系统</small></span>${icon('right')}</button>`;}
function secondBatchAction(a,b){
 const t=state.tasks.find(t=>t.id===(b.dataset.task||state.selectedTask));
 if(['example','proposal','replan','apply','undo','continue-result'].includes(a)&&state.tasks[0].status==='completed'){openSheet('task-already-done');return true;}
 if(a==='today')state.day=TODAY;
 if(a==='schedule')state.calendarWeek=Math.max(1,Math.min(20,Math.floor((Date.parse(state.day)-Date.parse('2026-08-31'))/604800000)+1));
 if(a==='detail'&&b.dataset.id==='java'&&!rows.some(r=>r.id==='java')){state.selectedTask='java';openSheet('task-detail');return true;}
 switch(a){
 case 'calendar-mode':state.calendarMode=b.dataset.mode;render({keepScroll:false});break;
 case 'calendar-day':state.day=b.dataset.day;render();break;
 case 'schedule-filter':state.scheduleFilter=b.dataset.filter;render();break;
 case 'week-prev':case 'week-next':case 'week-select':case 'week-current':{const delta=a==='week-prev'?-1:1;state.calendarWeek=a==='week-current'?4:a==='week-select'?Number(b.dataset.week):Math.max(1,Math.min(20,state.calendarWeek+delta));state.day=dateAdd(weekStart(state.calendarWeek),2);if(state.modal)closeSheet();render({keepScroll:false});break;}
 case 'plan-filter':state.planFilter=b.dataset.filter;render({keepScroll:false});break;
 case 'task-detail':case 'progress':case 'task-plan':state.selectedTask=b.dataset.task;openSheet(a);break;
 case 'save-progress':{if(state.offline){$('#progress-error').textContent='当前离线，尚未保存。';break;}const raw=$('#spent-minutes').value;const minutes=raw===''?null:Number(raw);const completed=$('#task-done').checked;if(minutes!=null&&(!Number.isInteger(minutes)||minutes<1||minutes>1440)){$('#progress-error').textContent='请输入1至1440之间的整数分钟数。';break;}if(minutes==null&&!completed){$('#progress-error').textContent='请填写投入时长，或勾选任务已完成。';break;}const id='progress-'+t.id+'-'+(t.version+1);const archived=completed&&t.id==='java'?rows.filter(r=>['java','deadline'].includes(r.id)):[];const receipt={id,minutes,completed,archived,oldRemaining:t.remaining};if(completed){t.status='completed';t.remaining=0;rows=rows.filter(r=>!archived.includes(r));}if(minutes!=null)rows.push({id,date:TODAY,title:t.title+' · 进度记录',start:null,end:null,category:t.category,tags:[...t.tags],kind:'progress',place:'实际投入记录',actual:minutes});t.records.push(receipt);t.version++;closeSheet();render();notify(completed?(archived.length?'任务已完成，剩余计划已取消':'任务已完成'):'实际投入已记录');break;}
 case 'undo-progress':{if(state.offline){notify('联网后才能撤销');break;}const r=t.records.at(-1);if(!r)break;rows=rows.filter(x=>x.id!==r.id);rows.push(...r.archived);t.status='active';t.remaining=r.oldRemaining;t.records.pop();t.version++;closeSheet();render();notify('完成记录已撤销');break;}
 case 'semester-week':state.semesterWeek=Number(b.dataset.week);render();break;
 case 'semester-filter':state.semesterFilter=b.dataset.filter;render();break;
 case 'semester-current':state.semesterWeek=4;render();break;
 case 'semester-calendar':state.calendarWeek=state.semesterWeek;state.day=weekStart(state.semesterWeek);navigate('schedule');break;
 case 'exam-review':state.selectedTask='prob-review';openSheet('task-detail');break;
 case 'confirm-import':if(state.offline){notify('当前离线，暂时无法导入');break;}openSheet('import-result');break;
 case 'load-failure':state.loadFailure=true;navigate('schedule');break;
 case 'retry-calendar':if(state.offline){notify('当前离线，已有记录已保留');break;}state.loadFailure=false;render();notify('示例记录已更新');break;
 default:return false;
 }return true;
}
document.addEventListener('input',event=>{if(event.target.id==='school-query'){const term=event.target.value.trim();$('#school-result').innerHTML=!term||'河南工业大学'.includes(term)?schoolChoice():'<div class="empty-state"><h3>暂未适配这所学校</h3><p>目前可以使用河南工业大学的示例导入。</p></div>';}});
document.addEventListener('input',event=>{if(event.target.id==='spent-minutes'&&$('#progress-error'))$('#progress-error').textContent='';});
document.addEventListener('change',event=>{if(event.target.id==='task-done'&&$('#progress-error'))$('#progress-error').textContent='';});
